INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_039_M4_S5', 'processing-property relations', '5', 'processing-property relations: Links between manufacturing or heat-treatment processes, resulting microstructure, and material properties. In Polymers and Ceramics, the focus is on the analysis, design, implementation, interpretation, or evaluation of processing-property relations within Engineering Materials, particularly where the Polymers and Ceramics module establishes its technical context.', 'SSD_COURSE_039_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M5_S1', 'fibres', '1', 'fibres: High-strength reinforcement elements used to carry load in composite materials. In Composite Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of fibres within Engineering Materials, particularly where the Composite Materials module establishes its technical context.', 'SSD_COURSE_039_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M5_S2', 'matrices', '2', 'matrices: Continuous phases that bind and support reinforcement in composite materials and transfer loads between constituents. In Composite Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of matrices within Engineering Materials, particularly where the Composite Materials module establishes its technical context.', 'SSD_COURSE_039_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M5_S3', 'laminates', '3', 'laminates: Layered composite structures formed by stacking plies with specified orientations and properties. In Composite Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of laminates within Engineering Materials, particularly where the Composite Materials module establishes its technical context.', 'SSD_COURSE_039_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M5_S4', 'anisotropy', '4', 'anisotropy: Dependence of a material''s properties on measurement or loading direction. In Composite Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of anisotropy within Engineering Materials, particularly where the Composite Materials module establishes its technical context.', 'SSD_COURSE_039_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M5_S5', 'failure mechanisms', '5', 'failure mechanisms: Physical processes such as fracture, fatigue, wear, corrosion, creep, or delamination that cause a material or component to lose required function. In Composite Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of failure mechanisms within Engineering Materials, particularly where the Composite Materials module establishes its technical context.', 'SSD_COURSE_039_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M6_S1', 'casting', '1', 'casting: Manufacturing by pouring or injecting molten material into a mould where it solidifies into the required shape. In Material Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of casting within Engineering Materials, particularly where the Material Processing module establishes its technical context.', 'SSD_COURSE_039_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M6_S2', 'forming', '2', 'forming: Shaping material by plastic deformation without removing substantial material. In Material Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of forming within Engineering Materials, particularly where the Material Processing module establishes its technical context.', 'SSD_COURSE_039_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M6_S3', 'machining', '3', 'machining: Removing material with cutting tools to achieve specified geometry, dimensions, and surface finish. In Material Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of machining within Engineering Materials, particularly where the Material Processing module establishes its technical context.', 'SSD_COURSE_039_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M6_S4', 'joining', '4', 'joining: Connecting separate components using processes such as welding, brazing, soldering, adhesive bonding, or mechanical fastening. In Material Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of joining within Engineering Materials, particularly where the Material Processing module establishes its technical context.', 'SSD_COURSE_039_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M6_S5', 'additive manufacturing', '5', 'additive manufacturing: Building parts layer by layer from digital geometry rather than removing material from a bulk stock. In Material Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of additive manufacturing within Engineering Materials, particularly where the Material Processing module establishes its technical context.', 'SSD_COURSE_039_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M7_S1', 'Ashby-style selection', '1', 'Ashby-style selection refers to the process of choosing among alternatives for ashby-style selection using defined performance, service, design, and constraint criteria. In Material Selection and Failure, the focus is on the analysis, design, implementation, interpretation, or evaluation of Ashby-style selection within Engineering Materials, particularly where the Material Selection and Failure module establishes its technical context.', 'SSD_COURSE_039_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M7_S2', 'corrosion', '2', 'corrosion: Deterioration of a material through chemical or electrochemical interaction with its environment. In Material Selection and Failure, the focus is on the analysis, design, implementation, interpretation, or evaluation of corrosion within Engineering Materials, particularly where the Material Selection and Failure module establishes its technical context.', 'SSD_COURSE_039_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M7_S3', 'fatigue', '3', 'fatigue: Progressive material damage caused by repeated or fluctuating loading, often leading to crack initiation and growth. In Material Selection and Failure, the focus is on the analysis, design, implementation, interpretation, or evaluation of fatigue within Engineering Materials, particularly where the Material Selection and Failure module establishes its technical context.', 'SSD_COURSE_039_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M7_S4', 'fracture', '4', 'fracture: Failure involving initiation and propagation of cracks through a material. In Material Selection and Failure, the focus is on the analysis, design, implementation, interpretation, or evaluation of fracture within Engineering Materials, particularly where the Material Selection and Failure module establishes its technical context.', 'SSD_COURSE_039_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M7_S5', 'wear', '5', 'wear: Progressive material loss or surface damage caused by mechanical interaction between contacting surfaces. In Material Selection and Failure, the focus is on the analysis, design, implementation, interpretation, or evaluation of wear within Engineering Materials, particularly where the Material Selection and Failure module establishes its technical context.', 'SSD_COURSE_039_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M7_S6', 'failure analysis', '6', 'failure analysis: Systematic investigation of why a material or component failed, using evidence from service conditions, fracture features, microstructure, and testing. In Material Selection and Failure, the focus is on the analysis, design, implementation, interpretation, or evaluation of failure analysis within Engineering Materials, particularly where the Material Selection and Failure module establishes its technical context.', 'SSD_COURSE_039_M7_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M1_S1', 'SI units', '1', 'SI units refers to the International System of Units used consistently for mass, length, time, temperature, amount of substance, and derived process quantities. In Units, Dimensions and Process Variables, the focus is on the analysis, design, implementation, interpretation, or evaluation of SI units within Chemical Process Calculations, particularly where the Units, Dimensions and Process Variables module establishes its technical context.', 'SSD_COURSE_040_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M1_S2', 'dimensional consistency', '2', 'dimensional consistency refers to the requirement that both sides of an engineering equation have compatible physical dimensions. In Units, Dimensions and Process Variables, the focus is on the analysis, design, implementation, interpretation, or evaluation of dimensional consistency within Chemical Process Calculations, particularly where the Units, Dimensions and Process Variables module establishes its technical context.', 'SSD_COURSE_040_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M1_S3', 'concentration', '3', 'concentration refers to the amount of a component present per unit volume, mass, or amount of mixture or solution. In Units, Dimensions and Process Variables, the focus is on the analysis, design, implementation, interpretation, or evaluation of concentration within Chemical Process Calculations, particularly where the Units, Dimensions and Process Variables module establishes its technical context.', 'SSD_COURSE_040_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M1_S4', 'flow rates', '4', 'flow rates refers to the rate at which mass, volume, or molar quantity passes through a process stream. In Units, Dimensions and Process Variables, the focus is on the analysis, design, implementation, interpretation, or evaluation of flow rates within Chemical Process Calculations, particularly where the Units, Dimensions and Process Variables module establishes its technical context.', 'SSD_COURSE_040_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M1_S5', 'pressure', '5', 'pressure: Normal force per unit area acting on a surface or within a fluid; in continuum fluid mechanics it is a scalar state variable whose spatial gradients can drive flow. In Units, Dimensions and Process Variables, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_040_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M1_S6', 'temperature', '6', 'temperature: Thermodynamic state variable indicating the thermal condition of a system and determining the direction of heat transfer under specified conditions. In Units, Dimensions and Process Variables, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_040_M1_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M2_S1', 'mass conservation', '1', 'mass conservation refers to the principle that total mass is conserved across a process subject to clearly defined system boundaries. In Material Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of mass conservation within Chemical Process Calculations, particularly where the Material Balances module establishes its technical context.', 'SSD_COURSE_040_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M2_S2', 'component balances', '2', 'component balances: Material balances written separately for individual chemical species or components. In Material Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of component balances within Chemical Process Calculations, particularly where the Material Balances module establishes its technical context.', 'SSD_COURSE_040_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M2_S3', 'basis selection', '3', 'basis selection: Choosing a convenient material or molar basis for process calculations so that material balances and related quantities can be formulated consistently. In Material Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of basis selection within Chemical Process Calculations, particularly where the Material Balances module establishes its technical context.', 'SSD_COURSE_040_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M2_S4', 'recycle', '4', 'recycle: Returning part of a process stream to an earlier unit to improve conversion, recovery, or process performance. In Material Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of recycle within Chemical Process Calculations, particularly where the Material Balances module establishes its technical context.', 'SSD_COURSE_040_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M2_S5', 'purge', '5', 'purge: Removing a portion of a recycle stream to prevent unwanted accumulation of inert or undesired components. In Material Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of purge within Chemical Process Calculations, particularly where the Material Balances module establishes its technical context.', 'SSD_COURSE_040_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M3_S1', 'stoichiometry', '1', 'stoichiometry: Quantitative relationships among reactants and products determined by balanced chemical equations. In Balances with Chemical Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of stoichiometry within Chemical Process Calculations, particularly where the Balances with Chemical Reactions module establishes its technical context.', 'SSD_COURSE_040_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M3_S2', 'conversion', '2', 'conversion refers to the fraction or percentage of a specified reactant that is consumed in a reaction. In Balances with Chemical Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of conversion within Chemical Process Calculations, particularly where the Balances with Chemical Reactions module establishes its technical context.', 'SSD_COURSE_040_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M3_S3', 'yield', '3', 'yield: Measure of desired product obtained relative to a specified theoretical, feed, or reactant basis; the exact definition depends on the process and stoichiometric basis. In Balances with Chemical Reactions, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_040_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M3_S4', 'selectivity', '4', 'selectivity refers to the extent to which a reaction or process favours formation of a desired product over competing products. In Balances with Chemical Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of selectivity within Chemical Process Calculations, particularly where the Balances with Chemical Reactions module establishes its technical context.', 'SSD_COURSE_040_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M3_S5', 'extent of reaction', '5', 'extent of reaction refers to a measure of the progress of a chemical reaction expressed through the change in the amount of a reacting species relative to its stoichiometric coefficient. In Balances with Chemical Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of extent of reaction within Chemical Process Calculations, particularly where the Balances with Chemical Reactions module establishes its technical context.', 'SSD_COURSE_040_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M4_S1', 'enthalpy', '1', 'enthalpy refers to a thermodynamic property used to represent energy changes in flowing process streams and phase changes. In Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of enthalpy within Chemical Process Calculations, particularly where the Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M4_S2', 'heat capacity', '2', 'heat capacity refers to the amount of heat required to raise the temperature of a substance or system by one degree under specified conditions. In Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat capacity within Chemical Process Calculations, particularly where the Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M4_S3', 'phase change', '3', 'phase change refers to a change between solid, liquid, vapour, or other phases involving associated energy and property changes. In Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of phase change within Chemical Process Calculations, particularly where the Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M4_S4', 'heat effects', '4', 'heat effects: Changes in enthalpy or temperature associated with heating, cooling, phase change, mixing, or chemical reaction in a process. In Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat effects within Chemical Process Calculations, particularly where the Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M4_S5', 'steady-state energy balances', '5', 'steady-state energy balances: Energy balances for processes in which stored mass and energy do not change with time. In Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of steady-state energy balances within Chemical Process Calculations, particularly where the Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M5_S1', 'coupled balances', '1', 'coupled balances: Simultaneous material and energy balances that must be solved together because process variables are interdependent. In Combined Material and Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of coupled balances within Chemical Process Calculations, particularly where the Combined Material and Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M5_S2', 'process streams', '2', 'process streams: Flows of material entering, leaving, or circulating between process units. In Combined Material and Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of process streams within Chemical Process Calculations, particularly where the Combined Material and Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M5_S3', 'heat integration basics', '3', 'heat integration basics: Basic methods for matching process heat sources and sinks to reduce external heating and cooling requirements. In Combined Material and Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat integration basics within Chemical Process Calculations, particularly where the Combined Material and Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M5_S4', 'degrees of freedom', '4', 'degrees of freedom refers to the number of independent variables that remain to be specified after accounting for equations and known information. In Combined Material and Energy Balances, the focus is on the analysis, design, implementation, interpretation, or evaluation of degrees of freedom within Chemical Process Calculations, particularly where the Combined Material and Energy Balances module establishes its technical context.', 'SSD_COURSE_040_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M6_S1', 'flowsheets', '1', 'flowsheets: Graphical representations of process units and the streams connecting them. In Process Flow Calculations, the focus is on the analysis, design, implementation, interpretation, or evaluation of flowsheets within Chemical Process Calculations, particularly where the Process Flow Calculations module establishes its technical context.', 'SSD_COURSE_040_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M6_S2', 'stream tables', '2', 'stream tables: Tabulated process-stream information such as flow, composition, temperature, pressure, and phase. In Process Flow Calculations, the focus is on the analysis, design, implementation, interpretation, or evaluation of stream tables within Chemical Process Calculations, particularly where the Process Flow Calculations module establishes its technical context.', 'SSD_COURSE_040_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M6_S3', 'process specifications', '3', 'process specifications: Specified operating or product requirements that constrain process calculations and design. In Process Flow Calculations, the focus is on the analysis, design, implementation, interpretation, or evaluation of process specifications within Chemical Process Calculations, particularly where the Process Flow Calculations module establishes its technical context.', 'SSD_COURSE_040_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M6_S4', 'numerical solution', '4', 'numerical solution: Use of numerical algorithms to solve process equations when analytical solutions are unavailable or inconvenient. In Process Flow Calculations, the focus is on the analysis, design, implementation, interpretation, or evaluation of numerical solution within Chemical Process Calculations, particularly where the Process Flow Calculations module establishes its technical context.', 'SSD_COURSE_040_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_040_M6_S5', 'sensitivity', '5', 'sensitivity refers to the change in a calculated process result caused by a change in an input parameter or assumption. In Process Flow Calculations, the focus is on the analysis, design, implementation, interpretation, or evaluation of sensitivity within Chemical Process Calculations, particularly where the Process Flow Calculations module establishes its technical context.', 'SSD_COURSE_040_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M1_S1', 'density', '1', 'density: Mass per unit volume of a fluid. In Fluid Properties and Flow Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of density within Fluid Flow and Heat Transfer, particularly where the Fluid Properties and Flow Fundamentals module establishes its technical context.', 'SSD_COURSE_041_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M1_S2', 'viscosity', '2', 'viscosity refers to a measure of a fluid’s resistance to deformation and flow, arising from internal friction and relating shear stress to velocity gradient under Newtonian conditions. In Fluid Properties and Flow Fundamentals, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M1_S3', 'Newtonian fluids', '3', 'Newtonian fluids: Fluids whose shear stress is proportional to shear rate, with viscosity remaining approximately constant at a given temperature and pressure. In Fluid Properties and Flow Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of Newtonian fluids within Fluid Flow and Heat Transfer, particularly where the Fluid Properties and Flow Fundamentals module establishes its technical context.', 'SSD_COURSE_041_M1_S3', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;